    let reactionAdmissionEntered!: () => void;
    const oldCallbacksReleased = new Promise<void>((resolve) => {
      releaseOldCallbacks = resolve;
    });
    const messageAdmissionReached = new Promise<void>((resolve) => {
      messageAdmissionEntered = resolve;
    });
