    const execute = vi.fn(async (_input: unknown) => ({
      exitCode: 0,
      signal: null,
      timedOut: false,
      errorMessage: null,
      summary: directFinals[execute.mock.calls.length - 1]!,
      provider: "test",
      model: "test-model",
    }));
    registerServerAdapter({
      type: adapterType,
      supportsLocalAgentJwt: false,
      execute,
      testEnvironment: async () => ({
        adapterType,
        status: "pass",
        checks: [],
        testedAt: new Date().toISOString(),
      }),
    });

