        await expect(context.repair()).resolves.toBe(true);
        await context.service.shutdown();
        restarted = createService(
          new FakeChatSdkRuntime(),
          context.providerFetch!,
          {
            publicBaseUrl: base,
            webhookPublicBaseUrl: "https://ingress.example:8443",
          },
        );
