        const text = restarted.runtime.endpoints.get(context.endpoint.id)!
          .posts[0]!.text;
        expect(text).toBe(
          expected
            ? `${context.result.summary}\n\n[Open this Paperclip task](${expected}/issues/${context.issue.id})`
            : context.result.summary,
        );
