        lane.setHook(undefined);
        await lane.restart();
        expect((await lane.deliver(draftId)).status).toBe(200);
        await lane.context.service.processPendingPublications();
        expect(lane.requests).toHaveLength(before);
        const [current] = await db
          .select()
